# MATLAB Program: Ultrasound Signal Conversion (Voltage vs Time → Magnitude(dB) vs Frequency(MHz))

```matlab
%% ========================================================================
% Ultrasound Signal Analysis: Voltage vs Time → Magnitude(dB) vs Frequency(MHz)
% =========================================================================
% This program converts an ultrasound signal from the time domain 
% (Voltage vs Time) to the frequency domain (Magnitude in dB vs Frequency in MHz)
% using the Fast Fourier Transform (FFT).
%
% Author: [Your Name]
% Date: [Current Date]
%% ========================================================================

clear; clc; close all;

%% ===================== USER CONFIGURATION ===============================
% Choose data source: 'file' to load from file, 'simulate' to generate sample
dataSource = 'simulate'; % Change to 'file' to load real data

%% ===================== DATA ACQUISITION ================================
switch dataSource
    case 'file'
        %------------------------------------------------------------------
        % OPTION 1: Load data from file
        %------------------------------------------------------------------
        % Supported formats: .csv, .txt, .mat, .xlsx
        % Expected format: Column 1 = Time (seconds), Column 2 = Voltage (V)
        %------------------------------------------------------------------

        [fileName, filePath] = uigetfile({'*.csv;*.txt;*.xlsx;*.mat', ...
            'Data Files (*.csv, *.txt, *.xlsx, *.mat)'}, ...
            'Select Ultrasound Signal File');

        if isequal(fileName, 0)
            error('No file selected. Program terminated.');
        end

        fullPath = fullfile(filePath, fileName);
        [~, ~, ext] = fileparts(fullPath);

        switch lower(ext)
            case '.mat'
                loadedData = load(fullPath);
                fieldNames = fieldnames(loadedData);
                % Assume first field contains [time, voltage] matrix
                data = loadedData.(fieldNames{1});
                time = data(:, 1);       % Time in seconds
                voltage = data(:, 2);    % Voltage in Volts

            case {'.csv', '.txt'}
                data = readmatrix(fullPath);
                time = data(:, 1);       % Time in seconds
                voltage = data(:, 2);    % Voltage in Volts

            case '.xlsx'
                data = readmatrix(fullPath);
                time = data(:, 1);       % Time in seconds
                voltage = data(:, 2);    % Voltage in Volts

            otherwise
                error('Unsupported file format: %s', ext);
        end

        % Calculate sampling parameters from data
        dt = mean(diff(time));          % Average time step (seconds)
        Fs = 1 / dt;                    % Sampling frequency (Hz)
        N = length(voltage);            % Number of samples

        fprintf('File loaded: %s\n', fileName);
        fprintf('Number of samples: %d\n', N);
        fprintf('Sampling frequency: %.2f MHz\n', Fs/1e6);
        fprintf('Signal duration: %.2f µs\n', (time(end)-time(1))*1e6);

    case 'simulate'
        %------------------------------------------------------------------
        % OPTION 2: Generate simulated ultrasound signal
        %------------------------------------------------------------------
        % Typical ultrasound parameters:
        %   - Center frequency: 1-20 MHz (medical), up to 100 MHz (industrial)
        %   - Sampling rate: at least 4x center frequency (Nyquist)
        %------------------------------------------------------------------

        % Sampling parameters
        Fs = 100e6;                     % Sampling frequency: 100 MHz
        T_duration = 10e-6;             % Signal duration: 10 microseconds
        dt = 1/Fs;                      % Time step
        time = (0:dt:T_duration-dt)';   % Time vector (seconds)
        N = length(time);               % Number of samples

        % Ultrasound pulse parameters
        f_center = 5e6;                 % Center frequency: 5 MHz
        bandwidth = 3e6;                % Bandwidth: 3 MHz (-6dB)
        pulse_delay = 3e-6;             % Pulse arrival time: 3 µs
        amplitude = 1.0;                % Peak voltage (V)

        % Generate Gaussian-modulated ultrasound pulse (typical A-scan)
        sigma = 1 / (2 * pi * bandwidth / 2.355); % Gaussian width from bandwidth
        gaussian_envelope = amplitude * exp(-((time - pulse_delay).^2) / (2 * sigma^2));
        pulse1 = gaussian_envelope .* sin(2 * pi * f_center * (time - pulse_delay));

        % Add a second echo (reflected pulse, attenuated and delayed)
        echo_delay = 6e-6;             % Echo arrival time
        echo_amplitude = 0.4;          % Attenuated amplitude
        gaussian_echo = echo_amplitude * exp(-((time - echo_delay).^2) / (2 * sigma^2));
        pulse2 = gaussian_echo .* sin(2 * pi * f_center * (time - echo_delay));

        % Add a third harmonic component (tissue harmonic imaging)
        harmonic_delay = 6e-6;
        harmonic_amp = 0.15;
        sigma_h = sigma * 0.8;
        gaussian_harmonic = harmonic_amp * exp(-((time - harmonic_delay).^2) / (2 * sigma_h^2));
        pulse3 = gaussian_harmonic .* sin(2 * pi * 2 * f_center * (time - harmonic_delay));

        % Combine signals and add noise
        SNR_dB = 30;                    % Signal-to-noise ratio in dB
        noise = amplitude * 10^(-SNR_dB/20) * randn(N, 1);
        voltage = pulse1 + pulse2 + pulse3 + noise;

        fprintf('Simulated ultrasound signal generated.\n');
        fprintf('Center frequency: %.1f MHz\n', f_center/1e6);
        fprintf('Sampling frequency: %.1f MHz\n', Fs/1e6);
        fprintf('Number of samples: %d\n', N);
        fprintf('Signal duration: %.1f µs\n', T_duration*1e6);
end

%% ===================== SIGNAL PREPROCESSING ============================
% Remove DC offset
voltage_dc_removed = voltage - mean(voltage);

% Apply window function to reduce spectral leakage
% Options: 'hann', 'hamming', 'blackman', 'kaiser', 'none'
windowType = 'hann';

switch windowType
    case 'hann'
        w = hann(N);
        windowName = 'Hann';
    case 'hamming'
        w = hamming(N);
        windowName = 'Hamming';
    case 'blackman'
        w = blackman(N);
        windowName = 'Blackman';
    case 'kaiser'
        beta = 5;  % Kaiser window parameter
        w = kaiser(N, beta);
        windowName = sprintf('Kaiser (β=%d)', beta);
    case 'none'
        w = ones(N, 1);
        windowName = 'Rectangular (None)';
    otherwise
        w = hann(N);
        windowName = 'Hann';
end

% Apply window
voltage_windowed = voltage_dc_removed .* w;

% Window amplitude correction factor (for accurate magnitude)
windowCorrectionFactor = mean(w);

%% ===================== FFT COMPUTATION =================================
% Zero-padding for improved frequency resolution (optional)
NFFT = 2^nextpow2(N);                  % Next power of 2 for efficiency
% NFFT = N;                             % Uncomment for no zero-padding

% Compute FFT
V_fft = fft(voltage_windowed, NFFT);

% Single-sided spectrum (positive frequencies only)
V_fft_single = V_fft(1:NFFT/2+1);

% Magnitude spectrum (correct for FFT scaling and window)
magnitude = (2 / (N * windowCorrectionFactor)) * abs(V_fft_single);
magnitude(1) = magnitude(1) / 2;       % DC component (no factor of 2)
magnitude(end) = magnitude(end) / 2;   % Nyquist component (no factor of 2)

% Frequency vector
freq = Fs * (0:(NFFT/2)) / NFFT;       % Frequency in Hz
freq_MHz = freq / 1e6;                  % Convert to MHz

% Convert magnitude to dB (relative to maximum or absolute reference)
% Option 1: Relative to peak (normalized)
mag_dB = 20 * log10(magnitude / max(magnitude));

% Option 2: Absolute dB (relative to 1V)
mag_dB_absolute = 20 * log10(magnitude + eps);  % eps prevents log(0)

% Power Spectral Density (optional)
PSD = (magnitude.^2) / (2 * Fs/N);     % V²/Hz
PSD_dB = 10 * log10(PSD + eps);

%% ===================== FREQUENCY ANALYSIS ==============================
% Find peak frequency
[peakMag, peakIdx] = max(magnitude);
peakFreq_MHz = freq_MHz(peakIdx);
peakMag_dB = mag_dB_absolute(peakIdx);

% Find -6dB bandwidth (common in ultrasound)
threshold_6dB = peakMag / 2;           % -6dB = half amplitude
aboveThreshold = magnitude >= threshold_6dB;
freqIndices = find(aboveThreshold);

if ~isempty(freqIndices)
    f_low_6dB = freq_MHz(freqIndices(1));
    f_high_6dB = freq_MHz(freqIndices(end));
    bandwidth_6dB = f_high_6dB - f_low_6dB;
    fractionalBW = 100 * bandwidth_6dB / peakFreq_MHz;
else
    f_low_6dB = NaN; f_high_6dB = NaN;
    bandwidth_6dB = NaN; fractionalBW = NaN;
end

% Find -20dB bandwidth
threshold_20dB = peakMag * 10^(-20/20);
aboveThreshold_20dB = magnitude >= threshold_20dB;
freqIndices_20dB = find(aboveThreshold_20dB);

if ~isempty(freqIndices_20dB)
    f_low_20dB = freq_MHz(freqIndices_20dB(1));
    f_high_20dB = freq_MHz(freqIndices_20dB(end));
    bandwidth_20dB = f_high_20dB - f_low_20dB;
else
    f_low_20dB = NaN; f_high_20dB = NaN; bandwidth_20dB = NaN;
end

%% ===================== DISPLAY RESULTS =================================
fprintf('\n========== FREQUENCY ANALYSIS RESULTS ==========\n');
fprintf('Peak Frequency:       %.3f MHz\n', peakFreq_MHz);
fprintf('Peak Magnitude:       %.2f dB (ref: 1V)\n', peakMag_dB);
fprintf('Peak Voltage:         %.4f V\n', peakMag);
fprintf('-6dB Bandwidth:       %.3f MHz (%.1f - %.1f MHz)\n', ...
    bandwidth_6dB, f_low_6dB, f_high_6dB);
fprintf('Fractional Bandwidth: %.1f%%\n', fractionalBW);
fprintf('-20dB Bandwidth:      %.3f MHz (%.1f - %.1f MHz)\n', ...
    bandwidth_20dB, f_low_20dB, f_high_20dB);
fprintf('Frequency Resolution: %.3f kHz\n', (Fs/NFFT)/1e3);
fprintf('Window Function:      %s\n', windowName);
fprintf('FFT Size:             %d points\n', NFFT);
fprintf('================================================\n');

%% ===================== PLOTTING ========================================

figure('Name', 'Ultrasound Signal Analysis', ...
    'Position', [50, 50, 1400, 900], 'Color', 'w');

% ---- Plot 1: Time Domain Signal (Voltage vs Time) ----
subplot(2, 2, 1);
plot(time * 1e6, voltage, 'b-', 'LineWidth', 1.0);
hold on;
plot(time * 1e6, abs(hilbert(voltage_dc_removed)), 'r--', 'LineWidth', 1.0);
hold off;
xlabel('Time (µs)', 'FontSize', 12, 'FontWeight', 'bold');
ylabel('Voltage (V)', 'FontSize', 12, 'FontWeight', 'bold');
title('Time Domain: Voltage vs Time', 'FontSize', 14, 'FontWeight', 'bold');
legend('Signal', 'Envelope', 'Location', 'best');
grid on;
set(gca, 'FontSize', 11);
xlim([time(1)*1e6, time(end)*1e6]);

% ---- Plot 2: Windowed Signal ----
subplot(2, 2, 2);
plot(time * 1e6, voltage_windowed, 'Color', [0, 0.5, 0], 'LineWidth', 1.0);
xlabel('Time (µs)', 'FontSize', 12, 'FontWeight', 'bold');
ylabel('Voltage (V)', 'FontSize', 12, 'FontWeight', 'bold');
title(sprintf('Windowed Signal (%s Window)', windowName), ...
    'FontSize', 14, 'FontWeight', 'bold');
grid on;
set(gca, 'FontSize', 11);
xlim([time(1)*1e6, time(end)*1e6]);

% ---- Plot 3: Frequency Domain - Magnitude (dB) vs Frequency (MHz) ----
subplot(2, 2, 3);
plot(freq_MHz, mag_dB, 'b-', 'LineWidth', 1.5);
hold on;

% Mark peak frequency
plot(peakFreq_MHz, 0, 'rv', 'MarkerSize', 10, 'MarkerFaceColor', 'r');

% Draw -6dB bandwidth
if ~isnan(bandwidth_6dB)
    yline(-6, 'r--', '-6 dB', 'LineWidth', 1.2, 'FontSize', 10, ...
        'LabelHorizontalAlignment', 'right');
    % Shade -6dB bandwidth region
    xPatch = [f_low_6dB, f_high_6dB, f_high_6dB, f_low_6dB];
    yPatch = [-80, -80, 0, 0];
    patch(xPatch, yPatch, 'r', 'FaceAlpha', 0.08, 'EdgeColor', 'none');
end

% Draw -20dB line
yline(-20, 'm--', '-20 dB', 'LineWidth', 1.0, 'FontSize', 10, ...
    'LabelHorizontalAlignment', 'right');

hold off;
xlabel('Frequency (MHz)', 'FontSize', 12, 'FontWeight', 'bold');
ylabel('Magnitude (dB)', 'FontSize', 12, 'FontWeight', 'bold');
title('Frequency Domain: Magnitude (dB) vs Frequency (MHz)', ...
    'FontSize', 14, 'FontWeight', 'bold');
legend(sprintf('Spectrum (Peak: %.2f MHz)', peakFreq_MHz), ...
    'Peak', 'Location', 'northeast');
grid on;
set(gca, 'FontSize', 11);
ylim([-80, 5]);
xlim([0, Fs/2e6]);  % Up to Nyquist frequency

% ---- Plot 4: Frequency Domain - Linear Magnitude vs Frequency (MHz) ----
subplot(2, 2, 4);
plot(freq_MHz, magnitude * 1e3, 'b-', 'LineWidth', 1.5);
hold on;
plot(peakFreq_MHz, peakMag * 1e3, 'rv', 'MarkerSize', 10, 'MarkerFaceColor', 'r');

% Draw -6dB bandwidth markers
if ~isnan(bandwidth_6dB)
    plot([f_low_6dB, f_high_6dB], [threshold_6dB, threshold_6dB] * 1e3, ...
        'r--', 'LineWidth', 1.5);
    plot(f_low_6dB, threshold_6dB * 1e3, 'rs', 'MarkerSize', 8, 'MarkerFaceColor', 'r');
    plot(f_high_6dB, threshold_6dB * 1e3, 'rs', 'MarkerSize', 8, 'MarkerFaceColor', 'r');
end

hold off;
xlabel('Frequency (MHz)', 'FontSize', 12, 'FontWeight', 'bold');
ylabel('Magnitude (mV)', 'FontSize', 12, 'FontWeight', 'bold');
title('Frequency Domain: Linear Magnitude vs Frequency (MHz)', ...
    'FontSize', 14, 'FontWeight', 'bold');

legendStr = {sprintf('Spectrum (Peak: %.2f MHz)', peakFreq_MHz), 'Peak'};
if ~isnan(bandwidth_6dB)
    legendStr{end+1} = sprintf('-6dB BW: %.2f MHz', bandwidth_6dB);
end
legend(legendStr, 'Location', 'northeast');
grid on;
set(gca, 'FontSize', 11);
xlim([0, Fs/2e6]);

% Add overall title
sgtitle('Ultrasound Signal: Time Domain → Frequency Domain Conversion', ...
    'FontSize', 16, 'FontWeight', 'bold');

%% ===================== ZOOMED FREQUENCY PLOT ===========================
figure('Name', 'Zoomed Frequency Spectrum', ...
    'Position', [100, 100, 1000, 500], 'Color', 'w');

% Determine zoom range (around peak ± some margin)
zoomMargin = 10; % MHz
freqMin = max(0, peakFreq_MHz - zoomMargin);
freqMax = min(Fs/2e6, peakFreq_MHz + zoomMargin);

plot(freq_MHz, mag_dB, 'b-', 'LineWidth', 2);
hold on;
plot(peakFreq_MHz, 0, 'rv', 'MarkerSize', 12, 'MarkerFaceColor', 'r');

